// Generate TS types from CORE's JSON Schema (contract C3: Rust serde -> JSON Schema -> TS).
// Input:  <repo>/schema/v1/*.schema.json (owned by CORE), or LOOM_SCHEMA_DIR.
// Output: src/proto/gen/<name>.ts, src/proto/gen/index.ts, src/proto/gen/SCHEMA_SHA256.
// `--check` regenerates in memory and fails if the committed output differs
// (schema drift or a hand edit). Generated files must never be edited by hand.
import { createHash } from 'node:crypto';
import { readFile, readdir, writeFile, mkdir, rm } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { compile } from 'json-schema-to-typescript';

const here = path.dirname(fileURLToPath(import.meta.url));
const uiRoot = path.resolve(here, '..');
const schemaDir = process.env.LOOM_SCHEMA_DIR ?? path.resolve(uiRoot, '..', 'schema', 'v1');
const outDir = path.join(uiRoot, 'src', 'proto', 'gen');
const check = process.argv.includes('--check');

const BANNER = '// GENERATED by scripts/gen-schema.ts from schema/v1 — do not edit.\n/* eslint-disable */\n';

function moduleName(file: string): string {
  return file.replace(/\.schema\.json$/, '');
}

async function main(): Promise<void> {
  const files = (await readdir(schemaDir)).filter((f) => f.endsWith('.schema.json')).sort();
  if (files.length === 0) throw new Error(`no *.schema.json in ${schemaDir}`);
  const hash = createHash('sha256');
  const out = new Map<string, string>();
  for (const f of files) {
    const raw = await readFile(path.join(schemaDir, f), 'utf8');
    hash.update(f).update('\0').update(raw).update('\0');
    const schema = JSON.parse(raw);
    const ts = await compile(schema, schema.title ?? moduleName(f), {
      bannerComment: '',
      additionalProperties: false,
      strictIndexSignatures: true,
      unreachableDefinitions: true,
      format: true,
      cwd: schemaDir,
      declareExternallyReferenced: true,
    });
    out.set(`${moduleName(f)}.ts`, BANNER + ts);
  }
  // Each schema inlines its $defs, so shared names repeat across modules; the
  // index re-exports module namespaces instead of flattening to avoid clashes.
  const index =
    BANNER +
    [...out.keys()]
      .map((f) => {
        const m = f.replace(/\.ts$/, '');
        const ns = m.replace(/_([a-z0-9])/g, (_, c: string) => c.toUpperCase());
        return `export * as ${ns} from './${m}';`;
      })
      .join('\n') +
    '\n';
  out.set('index.ts', index);
  out.set('SCHEMA_SHA256', `${hash.digest('hex')}\n`);

  if (check) {
    const drift: string[] = [];
    for (const [name, content] of out) {
      const cur = await readFile(path.join(outDir, name), 'utf8').catch(() => null);
      if (cur !== content) drift.push(name);
    }
    const existing = await readdir(outDir).catch(() => [] as string[]);
    for (const name of existing) if (!out.has(name)) drift.push(`${name} (stale)`);
    if (drift.length) {
      console.error(`schema drift: ${drift.length} file(s) differ — run pnpm gen:schema\n  ${drift.join('\n  ')}`);
      process.exit(1);
    }
    console.log(`schema ok: ${files.length} schemas, sha256 ${out.get('SCHEMA_SHA256')?.trim()}`);
    return;
  }
  await rm(outDir, { recursive: true, force: true });
  await mkdir(outDir, { recursive: true });
  for (const [name, content] of out) await writeFile(path.join(outDir, name), content);
  console.log(`generated ${files.length} modules into src/proto/gen`);
}

main().catch((e: unknown) => {
  console.error(e);
  process.exit(1);
});
